// NAIVE — DO NOT DO THIS. Read-check-write race.
public boolean checkinNaive(String seatId, String passengerId) {
    Seat seat = db.query("SELECT status FROM seats WHERE seat_id = ?", seatId);
    if (seat.status.equals("AVAILABLE")) {
        // Another request can slip in HERE.
        db.exec("UPDATE seats SET status='ASSIGNED', passenger_id=? WHERE seat_id=?",
            passengerId, seatId);
        return true;
    }
    return false;
}

public CheckinResult confirmSeat(String flightId, String seatId,
    String passengerId, String idemKey) {
  // 1. Idempotency first — outside the hot lock.
  CheckinRecord existing = db.findByIdemKey(idemKey);
  if (existing != null) return CheckinResult.duplicate(existing);

  return db.inTransaction(tx -> {
    // 2. Lock ONLY the target seat row. Short transaction.
    Seat s = tx.queryOne(
      "SELECT status, version FROM seats " +
      "WHERE flight_id=? AND seat_id=? FOR UPDATE",
      flightId, seatId);
    if (s == null || !s.status.equals("HELD") && !s.status.equals("AVAILABLE"))
      throw new SeatTakenException(seatId);
    // Verify caller owns the Redis hold (omitted) or allow AVAILABLE->ASSIGNED.
    int n = tx.exec(
      "UPDATE seats SET status='ASSIGNED', passenger_id=?, version=version+1 " +
      "WHERE flight_id=? AND seat_id=? AND status IN ('AVAILABLE','HELD')",
      passengerId, flightId, seatId);
    if (n == 0) throw new SeatTakenException(seatId);

    // 3. Insert checkin + outbox atomically. Unique idemKey dedups retries.
    CheckinRecord c = tx.insertCheckin(flightId, passengerId, seatId, idemKey);
    tx.insertOutbox("CHECKED_IN", c);
    return CheckinResult.ok(c);
  });
}
